select count(distinct s.customer_id) as kunden, count(*) as abos, count(*) filter (where ends_at is null) as ohne_ende, count(*) filter (where c.subscription_id is not null) as gekuendigt, count(*) filter (where c.subscription_id is not null and ends_at is null) as gek_ohne_ende
from subscriptions s left join cancellations c using(subscription_id)
where s.plan='pro_annual' and s.started_at < timestamptz '2026-10-01 00:00+00' and (s.ends_at is null or s.ends_at >= timestamptz '2026-10-01 00:00+00')

select count(*) n, count(distinct p.invoice_id) inv, count(distinct p.payment_id) pid, sum(p.amount_usd) total, sum(p.amount_usd) filter (where p.status='succeeded') ok, min(p.amount_usd) mn
from payments p join subscriptions s using(subscription_id)
where s.channel='web' and p.paid_at >= '2026-09-01' and p.paid_at < '2026-10-01'

select count(distinct s.customer_id) as kunden, count(*) as abos, count(*) filter (where ends_at is null) as offen, count(*) filter (where c.subscription_id is not null) as gekuendigt
from subscriptions s left join cancellations c using(subscription_id)
where s.plan='pro_annual' and s.started_at < timestamptz '2026-10-01 00:00:00+00' and (s.ends_at is null or s.ends_at >= timestamptz '2026-09-30 00:00:00+00')
